      "game_cities2.meta_title": `Cities: Skylines II — Motor de videojuegos | Gabriel Díaz Bernal`,
      "game_cities2.meta_description": `Trabajo de motor en Cities: Skylines II (Paradox Interactive / Colossal Order): simulación a gran escala y optimización de Unity Engine.`,
      "game_cities2.eyebrow": `Motor de videojuegos`,
      "game_cities2.title": `Cities: Skylines II`,
      "game_cities2.subtitle": `Trabajo de motor en un simulador de ciudades a gran escala: gestión de decenas de miles de agentes simultáneos y optimización de Unity Engine para simulación masiva.`,
      "game_cities2.stat1_value": `Paradox Interactive`, "game_cities2.stat1_label": `Editor`,
